package com.example.discussions.exception;
import org.springframework.dao.DataIntegrityViolationException;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler {record ErrorBody(Instant timestamp,int status,String error,Map<String,String> fields){}@ExceptionHandler(ApiException.class)ResponseEntity<ErrorBody> api(ApiException e){return ResponseEntity.status(e.status).body(new ErrorBody(Instant.now(),e.status.value(),e.getMessage(),Map.of()));}@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<ErrorBody> validation(MethodArgumentNotValidException e){Map<String,String> fields=new HashMap<>();e.getBindingResult().getFieldErrors().forEach(x->fields.put(x.getField(),x.getDefaultMessage()));return ResponseEntity.badRequest().body(new ErrorBody(Instant.now(),400,"Ошибка проверки данных",fields));}@ExceptionHandler(DataIntegrityViolationException.class)ResponseEntity<ErrorBody> conflict(){return ResponseEntity.status(409).body(new ErrorBody(Instant.now(),409,"Конфликт данных",Map.of()));}}
